mapper.select:
SELECT  FROM ops_exception_case
WHERE tenant_id=#{tenantId} AND store_id=#{storeId}
AND state=#{state}AND severity=#{severity}
ORDER BY FIELD(severity,'P0','P1','P2','P3'),last_observed_at DESC,case_id LIMIT #{limit}

mapper.update:
UPDATE ops_exception_case SET state=#{toState},assignee_user_id=#{assigneeUserId},
    lease_expires_at=#{leaseExpiresAt},resolver_user_id=#{resolverUserId},reviewer_user_id=#{reviewerUserId},
    record_version=record_version+1,updated_at=#{changedAt}
    WHERE tenant_id=#{tenantId} AND case_id=#{caseId} AND state=#{fromState} AND record_version=#{expectedVersion}

mapper.select:
SELECT plan_id planId,case_id caseId,action_code actionCode,summary_sha256 summarySha256,planner_user_id plannerUserId,
  state,created_at createdAt FROM ops_exception_action_plan WHERE tenant_id=#{tenantId} AND case_id=#{caseId}
ORDER BY created_at DESC,plan_id DESC LIMIT 1

mapper.update:
UPDATE ops_exception_repair_command SET state=#{toState},owner_result_reference=#{ownerResultReference},
    owner_result_sha256=#{ownerResultSha256},observed_at=#{observedAt}
    WHERE tenant_id=#{tenantId} AND repair_command_id=#{repairCommandId} AND state=#{fromState}

mapper.select:
SELECT command_id commandId,case_id caseId,operation,idempotency_key idempotencyKey,request_sha256 requestSha256,
  result_state resultState,created_at createdAt FROM ops_exception_command
WHERE tenant_id=#{tenantId} AND operation=#{operation} AND idempotency_key=#{idempotencyKey}
